// nisargadatta_te.dart
// Nisargadatta maharaj quotes and articles (Telugu)

import '../articlesquotes.dart';

final nisargadattaSaintTe = Saint(
  'nisargadatta',
  'Nisargadatta maharaj',
  'assets/images/nisargadatta.jpg',
  [
    'మీరు మీను ఎలా భావిస్తారో, ఆ విధంగా మీరు కాదు. మీరు ఎవరో తెలుసుకోండి.',
    'నిజం చనదు, అబద్ధం ఎప్పుడూ జీవించలేదు.',
    'జ్ఞానం నాకు నేను ఏమి కాదు అని చెప్తుంది. ప్రేమ నాకు నేను అన్నీ అని చెప్తుంది. ఈ రెండింటి మధ్య నా జీవితం ప్రవహిస్తుంది.',
    'మీరు పరమ సత్యం. చిన్న మనసు ఉండకండి.',
    'మీరు ఏమిటో తెలుసుకోవాలంటే, మీరు మొదట మీకు ఏమిటో కాదో పరిశీలించి తెలుసుకోవాలి.',
    'మీ లోని చైతన్యం మరియు నా లోని చైతన్యం, బహుశా రెండు అనిపించినా, ఒకటే, ఏకత్వాన్ని అన్వేషించండి మరియు అది ప్రేమ.',
    'మీరు మీను నిర్వచించాలనే అభిరుచి నుండి విముక్తి పొందడం మాత్రమే అవసరం.',
    'ఒకసారి మీరు ఈ విషయాన్ని గ్రహిస్తే, మార్గమే లక్ష్యం మరియు మీరు ఎప్పుడూ మార్గంలో ఉన్నారు, లక్ష్యాన్ని చేరుకోవడానికి కాదు, దాని అందం మరియు జ్ఞానాన్ని ఆస్వాదించడానికి, జీవితం ఒక పనిగా ఉండటం ఆగుతుంది మరియు సహజంగా, సరళంగా మారుతుంది.',
    'మీరు శరీరం కాదు. మీరు మనసు కూడా కాదు. మీరు రెండు కనిపించే అవగాహన.',
    'మీ నిజమైన స్వరూపాన్ని తెలుసుకున్న క్షణం, మీరు ఏమీ భయపడరు.',
    'మీరు ఈ లేదా ఆ విషయం గా ఉండడం లేదా చేయడం గురించి ఊహించడం ఆపండి మరియు మీరు అన్ని విషయాల మూలం మరియు హృదయం అని తెలుసుకోవడం మీపై వెలుగొందుతుంది.',
    'మీరు అనుభవించే ఏది కూడా మీది కాదు. మీరు అనుభవించే ఏది కూడా మీతో సంబంధం లేదు.',
    'సాంప్రదాయ ప్రమాణాలను అన్ని విసర్జించండి. వాటిని సాంప్రదాయానికి అనుబంధితులపై వదిలేయండి.',
    'మీ నిజమైన ఇల్లు శూన్యంలో, అన్ని విషయాల ఖాళీగా ఉంది.',
    'నేను లోపల చూసినప్పుడు నేను ఏమి కాదు అని చూస్తే, అది జ్ఞానం. నేను బయట చూసినప్పుడు నేను అన్నీ అని చూస్తే, అది ప్రేమ.',
    'మనసు గహ్వరం సృష్టిస్తుంది, హృదయం దాన్ని దాటుతుంది.',
    'మీరు ఏమిటి అనుకుంటున్నారో, మీరు ఆ కాదు.',
    'మీరు మీను ఒక వ్యక్తిగా భావిస్తారు, కానీ మీరు ఒక వ్యక్తిగా జన్మించినది కాదు.',
    'నిజానికి మీరు ఒక వస్తువు కాదు, ఇతర వస్తువుల నుండి వేరుగా ఉన్నారు కూడా కాదు.',
    'అనుభవం కోసం చేసిన శోధన అన్ని ప్రయత్నాలలో అత్యంత ప్రమాదకరమైనది, ఎందుకంటే ఇది మీరు నివసిస్తున్న ప్రపంచాన్ని నాశనం చేస్తుంది.',
    'అన్ని విడిపోవడం, ప్రతి రకమైన దూరం మరియు పరాయిత్వం అబద్ధం.',
    'మీరు సమస్తాన్ని ఆవహించు చైతన్యానికి ప్రదర్శన మరియు వ్యక్తీకరణగా ఉన్న తుది సామర్థ్యం.',
    'వ్యక్తిగత అవసరాలకు రక్షణ అవసరం, నిజమైన అవసరాలకు రక్షణ అవసరం లేదు.',
    'మీరు బాధపడే దేనికీ కారణం మీ స్వంత ఊహ మాత్రమే.',
    'మీరు మీ స్వంత కల్పన తప్ప మరేమీ మీకు కష్టాన్ని కలిగించలేనని పూర్తి నిశ్చయంతో తెలుసుకున్నప్పుడు, మీరు మీ ఆకాంక్షలు మరియు భయాలను పక్కన పెట్టడం ప్రారంభిస్తారు.',
    'మీరు ప్రపంచంలో లేరు, ప్రపంచం మీలో ఉంది.',
    '\'నేను ఉన్నాను\' అనే భావన మీది. మీరు దీన్ని విడదీయలేరు, కానీ మీరు దీన్ని ఏదైనా impart చేయవచ్చు, ఉదాహరణకు \'నేను యువుడిని\', \'నేను ధనవంతుడిని\' మొదలైనవి.',
    'నొప్పి మరియు ఆనందం తీరాల మధ్య జీవన నది ప్రవహిస్తుంది. మనసు జీవనంతో ప్రవహించడానికి నిరాకరించినప్పుడు, మరియు తీరాల వద్ద చిక్కుకున్నప్పుడు మాత్రమే అది ఒక సమస్యగా మారుతుంది.',
    'స్వేచ్ఛ అనేది తెలిసినది నుండి ఉద్భవిస్తుంది.',
    'మీ బలహీనత మీకు ఈ ప్రపంచంలో జన్మించినట్లు ఉన్న నమ్మకానికి కారణం.',
    'మీ విమోచన కోసం మీ మేధస్సుపై ఆధారపడకండి. మీను బంధనంలోకి తీసుకువచ్చింది మీ మేధస్సు.',
    'నిజమైన గురువు జీవితం స్వయంగా ఉంది.',
    'మీరు దానిని పొందాల్సిన అవసరం లేదు, ఎందుకంటే మీరు అదే.',
    'ప్రేమ \'నేను అన్నీ\' అంటుంది. జ్ఞానం \'నేను ఏమి కాదు\' అంటుంది. ఈ రెండు మధ్య, నా జీవితం ప్రవహిస్తుంది.',
    'త్రయం: మనస్సు, ఆత్మ మరియు ఆత్మ, పరిశీలించినప్పుడు, ఏకత్వంగా మారుతుంది.',
    'సాధించడానికి ప్రయత్నించకుండా ఉండండి. మీ నిజమైన స్వభావం వెలువడనివ్వండి. మీ మనసును అన్వేషణతో కిరాయించకండి.',
    'మీ స్వంత ఆత్మ మీ తుది గురువు. బాహ్య గురువు కేవలం ఒక మైలురాయి మాత్రమే.',
    'మీ ప్రపంచంలో ప్రతి విషయానికి ప్రారంభం మరియు ముగింపు ఉండాలి. అది లేకపోతే, మీరు దానిని శాశ్వతం అంటారు.',
    'అనుభవించిన వ్యక్తి ప్రపంచాన్ని ఎలా ఉందో అలా చూస్తాడు: సారంలో ఒకటిగా, రూపంలో విభిన్నంగా.',
    'కల్పన లేకుండా చూడడం నేర్చుకోండి, వికృతీకరణ లేకుండా వినడం నేర్చుకోండి.',
    'మనస్సే మనస్సు ఉందని మీకు చెబుతుంది. మోసపోవద్దు.',
    'సత్యం మంచి ప్రవర్తనకు బహుమతి కాదు, లేదా కొన్ని పరీక్షలను పాస్ చేసేందుకు ప్రైజ్ కాదు.',
    'మీరు మనిషి అని భావించే దాని గురించి ఆలోచించండి, అది నిజంగా మనిషి కాదు.',
    'మీరు మీ కోసం ఒక జైలును నిర్మించడంలో చాలా శక్తిని పెట్టారు. ఇప్పుడు దాన్ని కూల్చడంలో అంతే శక్తిని ఖర్చు చేయండి.',
    'మీరు వ్యక్తి కాదు అని అర్థం చేసుకోవడానికి, ఆ వ్యక్తిని గమనించండి. ఆ వ్యక్తిని చైతన్యంలో ఒక వస్తువుగా చూడండి.',
    'శరీరం-మనసు ఐక్యతను వదలడంలో కష్టమేమిటి? చివరికి, మీరు శరీరం-మనసు కాదు.',
    'మీరు మరణాన్ని భయపడుతున్నారంటే, మీరు మీను తెలియకపోవడం వల్ల. నిజమైన మీరు మరణరహితుడే.',
    'మీరు మీరే అన్నది మరియు అన్నింటికంటే మించి ఉన్నది తెలుసుకోవడానికి మీకు అడ్డుపడుతున్నది మేధా, ఇది స్మృతిపై ఆధారపడి ఉంది.',
    'మనస్సు కాలంలో ఉంది, మనం కాలం కంటే మించి ఉన్నాము.',
    'మీరు ప్రేమే - మీరు భయపడకుండా ఉన్నప్పుడు.',
    'మీరు మీను ఎలా భావిస్తున్నారో అలా కాదు. మీరు శరీరం కాదు, మనస్సు కాదు, వ్యక్తిగా ఉండే భావన కూడా కాదు. మీరు ఈ అన్ని వస్తువులు కనిపించే మరియు మాయమయ్యే అకాల చైతన్యం.',
    'మీరు వ్యక్తిగా కాకుండా చైతన్యంగా మీను తెలుసుకున్న క్షణంలో, అన్ని బాధలు ముగుస్తాయి. మిగిలేది అనుభవం కాదు, మీ సహజ స్థితి అయిన శాంతి.',
    'శరీరం ఉన్నప్పుడు కంటే ముందే, ప్రపంచం కనిపించినప్పుడు కంటే ముందే, నువ్వు ఉన్నావు. అన్ని భావనలకు ముందు ఉన్న ఆ అనుభూతితో ఉండి, మిగతా అన్ని విషయాలను విడిచిపెట్టు.',
    '\'నేను ఉన్నాను\' అనేది మొదటి ద్వారం. దానితో స్థిరంగా ఉండండి. \'నేను ఉన్నాను\' కూడా కరిగినప్పుడు, పరమతత్త్వం మిగిలి ఉంటుంది.',
    'మీరు ప్రపంచంలో లేరు; ప్రపంచం మీలో ఉంది. మీరు మీ చైతన్యంలో మొత్తం విశ్వాన్ని మోస్తున్నారు.',
    'మీరు ఏమిటి అనేది తెలుసుకోవాలంటే, మీరు ఏమిటి కాదు అనేదాన్ని ముందుగా పరిశీలించాలి. చూడబడే, గ్రహించబడే లేదా అనుభవించబడే ఏదీ మీది కాదు.',
    'నిజమైన ఆత్మ సాధించాల్సినది కాదు. మీరు మీ గురించి ఉన్న అన్ని తప్పు భావనలను వదిలేసినప్పుడు మీరు ఉన్నది అదే.',
    'మీరు మీను పరిమితంగా ఊహిస్తారు, మరియు ఆ పరిమితి కారణంగా మీరు బాధపడతారు. నిజానికి, మీరు ఏమిటో దానికి ఎటువంటి సరిహద్దు లేదు.',
    'మీరు శరీర-మనసుతో గుర్తింపు ఇవ్వడం ఆపినప్పుడు, మీరు ఎప్పుడూ బంధితులుగా, ఎప్పుడూ కష్టాల్లో, ఎప్పుడూ అసంపూర్ణులుగా ఉండలేదని మీరు కనుగొంటారు.',
    'జ్ఞానం వ్యక్తిగతం కాదు. వ్యక్తి జ్ఞానంలో కనిపిస్తాడు, కానీ జ్ఞానం వ్యక్తికి చెందినది కాదు.',
    'చైతన్యం స్వయంగా ఒక తాత్కాలిక స్థితి. ఇది కనిపిస్తుంది మరియు అదృశ్యమవుతుంది. చైతన్యాన్ని తెలిసినది దానికి మించిపోయింది.',
    'అఖండం తన గురించి అవగాహన కలిగి ఉండదు. అవగాహన అనేది అఖండంలో ఉత్పన్నమయ్యే ఒక ఫెనామెనాన్, సముద్రంలో అలల వంటి.',
    'మీరు చైతన్యాన్ని మీ స్వరూపంగా భావిస్తారు, కానీ చైతన్యాన్ని కూడా గమనించబడుతుంది. చైతన్యాన్ని తెలుసుకునే దాన్ని కనుగొనండి.',
    'శరీరం మరియు ప్రపంచం చైతన్యంతో కలిసి ఉద్భవిస్తాయి. చైతన్యం లేకపోతే, ప్రపంచం కూడా ఉండదు.',
    'చైతన్యానికి ముందు, అనుభవం లేదు, కాలం లేదు, స్థలం లేదు — అయినప్పటికీ, మీరు ఉన్నారు. అది మీ నిజమైన స్వభావం.',
    'చైతన్యం శరీరంపై ఆధారపడి ఉంటుంది, కానీ పరమాత్మ ఏదైనా మీద ఆధారపడదు. తేడాను తెలుసుకోండి.',
    'మరణంలో చైతన్యం కరిగిపోయినప్పుడు, మీరు నిజంగా ఏమిటి అది చనిపోదు, ఎందుకంటే అది ఎప్పుడూ జన్మించలేదు.',
    'అబ్సొల్యూట్ గురించి మాట్లాడలేము. చెప్పబడే ఏది అయినా అది కేవలం చైతన్యం గురించి మాత్రమే.',
    'చైతన్యానికి మూలంలో ఉండండి, అప్పుడు మీరు దాన్ని అధిగమించగలరు.',
    'మీరు చైతన్యానికి జరిగిన చలనం ను వాస్తవంగా భావిస్తున్నారు. వాస్తవం అంటే కదలకుండా ఉండేది.',
    'మీ యొక్క ఏకైక సాధన \'నేను ఉన్నాను\' అనే భావనను పట్టుకోవడం మరియు మిగతా అన్ని విషయాలను అప్రతిహితంగా తిరస్కరించడం.',
    'మీరు కనిపించే దాన్ని మార్చడానికి ప్రయత్నించకండి. మీరు ఏమిటో మాత్రమే అర్థం చేసుకోండి, అప్పుడు ప్రతిదీ స్వయంగా మారుతుంది.',
    'ప్రయత్నం అవసరం, ప్రయత్న రహితత్వం కనుగొనబడే వరకు. అప్పుడు ప్రయత్నం కూడా మాయం అవుతుంది.',
    'ఆత్మ పరిశీలన మానసిక వ్యాయామం కాదు. ఇది కనిపించే ఏదీతో ఐక్యత కలిగి ఉండేందుకు నిరంతరం నిరాకరించడం.',
    'మీ ఆలోచనలను ఆకాశంలో కదులుతున్న మేఘాలను చూడటంలా చూడండి. వాటిని మీది అని భావించకండి.',
    'మనస్సు మనస్సును మించడానికి మీకు సహాయపడదు. దాన్ని అర్థం చేసుకోవడం ద్వారా మీరు దానిని మించాలి.',
    'మీరు మనసును గమనించినప్పుడు, మీరు దాని కంటే ముందే ఉన్నారు.',
    'ఎంత సమయం పడుతుందో అడగకండి. మీ పరిశోధనలో కృతఙ్ఞతతో మరియు నిజాయితీగా ఉండండి.',
    'మీరు మనసును శుద్ధి చేయాల్సిన అవసరం లేదు. కేవలం దానితో ఐక్యమవ్వడం ఆపండి.',
    'మౌనం శబ్దం లేకపోవడం కాదు; అది గుర్తింపు లేకపోవడం.',
    'వ్యక్తి అనేది జ్ఞాపకాలు, అలవాట్లు మరియు శిక్షణల యొక్క సమాహారం. మీరు ఆ సమాహారం కాదు.',
    'అహంకారం కేవలం ఒక ఆలోచన మాత్రమే - చైతన్యంవల్ల స్వీకరించిన ఒక తప్పు కేంద్రం.',
    'మీరు \'నేను బాధపడుతున్నాను\' అని చెప్పినప్పుడు, ఈ \'నేను\' ఎవరో పరిశీలించండి. మీరు దాన్ని కనుగొనరు.',
    '\'నేను చేసే వ్యక్తి\' అనే ఆలోచన బంధనమే. అది పోతే, స్వాతంత్ర్యం ఉంటుంది.',
    'వ్యక్తిత్వం వాస్తవం కాదు; ఇది చైతన్యమిచ్చే మాస్క్.',
    'మీరు మీను ఒక వ్యక్తిగా భావించినంత కాలం, మీరు భయంతో జీవిస్తారు.',
    'వ్యక్తిత్వ భావన శరీరంతో వస్తుంది మరియు దాని తోనే ముగుస్తుంది.',
    'మీరు శూన్యతను భయపడుతూ వ్యక్తికి cling చేస్తారు, కానీ ఆ శూన్యతనే శాంతి.',
    'వ్యక్తి కరిగినప్పుడు, మిగిలినది శూన్యత కాదు, సంపూర్ణత.',
    'అహంకారం నిరంతరాన్ని కోరుకుంటుంది; వాస్తవానికి అది లేదు.',
    'అన్ని బాధలు గుర్తింపు నుండి ఉత్పన్నమవుతాయి. మీరు తాత్కాలికాన్ని మీ స్వరూపంగా తీసుకుంటున్నందున మీరు బాధపడుతున్నారు.',
    'అసంపూర్ణత యొక్క భావన నుండి ఇష్టాలు ఉత్పన్నమవుతాయి, అది స్వయంగా అబద్ధం.',
    'భయము కేవలం వ్యక్తికి మాత్రమే ఉంటుంది. ఆత్మకు భయం తెలియదు.',
    'మీరు శరీరం కాదని తెలుసుకున్నప్పుడు, మరణం తన భయాన్ని కోల్పోతుంది.',
    'నొప్పి శారీరికం; బాధ మానసికం. మీరు అర్థం చేసుకోవడం ద్వారా బాధను అధిగమించవచ్చు.',
    'మీరు ఎదురు చేసే దాన్ని నిలబెడుతుంది. మీరు అర్థం చేసుకునే దాన్ని కరిగిస్తుంది.',
    'కామం అనేది భవిష్యత్తులో ప్రక్షిప్తమైన స్మృతి.',
    'స్వేచ్ఛ అనేది కోరిక యొక్క సాకారం కాదు, కానీ కోరిక నుండి విముక్తి.',
    'వేదన అనేది మీరు మీ గురించి తప్పుగా ఆలోచిస్తున్నారని మీకు సంకేతం ఇచ్చే ఒక సంకేతం.',
    'అసత్యమైన ఐడెంటిటీ ముగిసినప్పుడు, బాధ కూడా దానితో ముగుస్తుంది.',
    'ప్రపంచం అసత్యం కాదు, కానీ ఇది మీరు అనుకుంటున్నట్లు కాదు. ఇది చైతన్యానికి ఒక ప్రతిబింబం.',
    'ప్రపంచం నిజంగా కనిపిస్తుంది ఎందుకంటే మీరు దానిలో భాగంగా ఉన్నారని నమ్ముతారు.',
    'చైతన్యం నిశ్శబ్దంగా ఉన్నప్పుడు, ప్రపంచం నిశ్శబ్దంగా ఉంటుంది.',
    'బ్రహ్మాండము కేవలం దాన్ని అనుభవించినంత కాలమే ఉనికిలో ఉంది.',
    'మీరు ప్రపంచానికి వాస్తవాన్ని వ్యక్తిగతంగా తీసుకోవడం ద్వారా అందిస్తారు.',
    'ప్రపంచం చైతన్యానికి విడిగా స్వతంత్రంగా ఉండదు.',
    'సత్యం సులభం; మాయా సంక్లిష్టం.',
    'ప్రపంచం మంచి లేదా చెడు కాదు. ఇది కేవలం మీ అవగాహనను ప్రతిబింబిస్తుంది.',
    'మీరు \'నిజమైన జీవితం\' అని పిలిచేది అనుభవాల ప్రవాహం.',
    'ప్రపంచం ఒక ప్రదర్శన, కానీ చైతన్యం దాన్ని గంభీరంగా తీసుకుంటుంది.',
    'గురు మీకు కొత్తది ఇవ్వడు. అతను తప్పు అయినది తీసివేస్తాడు.',
    'కృప ఒక సంఘటన కాదు; అది మీ స్వభావం.',
    'మీరు సిద్ధంగా ఉన్నప్పుడు, బోధ మీను కనుగొంటుంది.',
    'గురు సూచిస్తాడు, కానీ మీరు చూడాలి.',
    'మీరు స్వయంగా నిర్ధారించుకునే వరకు బోధనపై నమ్మకం ఉంచండి.',
    'గురువుపై నమ్మకం అంటే మీ స్వంత ఆత్మపై నమ్మకం.',
    'పదాలు కేవలం సూచికలు మాత్రమే. వాటికి పట్టుబట్టకండి.',
    'అత్యున్నత ఉపదేశం మౌనం.',
    'ఒక నిజమైన గురువు అహంకారాన్ని సంతోషపరచడు; అతను దాన్ని నాశనం చేస్తాడు.',
    'అర్థం పూర్తయినప్పుడు, గురువు కనుమరుగవుతాడు.',
    'ముక్తి కాలంలో సాధించబడే విషయం కాదు. ఇది కాలం లేని దానిని గుర్తించడం.',
    'మీరు ఇప్పుడు స్వేచ్ఛగా ఉన్నారు, కానీ మీరు మీను బంధితుడిగా ఊహిస్తున్నారు.',
    'స్వాతంత్ర్యం అంటే మీకు ఇష్టమైనది చేయడం కాదు, కానీ కోరికల వల్ల బలవంతంగా చేయించబడకపోవడం.',
    'నేను లేని సమయంలో, బంధనం ఉండదు.',
    'ముక్తి అనేది అన్వేషణకు ముగింపు.',
    'ముక్తుడికి ఏమీ జరుగదు, ఎందుకంటే అది జరగడానికి ఎవరూ లేరు.',
    'ముక్తి స్థితి సాధారణ, సహజ, మరియు గమనించబడనిది.',
    'మీరు విముక్తి పొందరు; మీరు ఎప్పుడూ బంధితులుగా ఉండలేదని తెలుసుకుంటారు.',
    'అధికమైన స్థితి అసలు ఒక స్థితి కాదు.',
    'అజ్ఞానం ముగిసినప్పుడు, ప్రత్యేకమైనది ఏమి జరగదు — సత్యం కేవలం ప్రकटమవుతుంది.',
    'మీరు వాస్తవానికి ఒక భాగం కాదు. మీరు వాస్తవం స్వయంగా ఉన్నారు.',
    'ఏది కనిపిస్తుందో అది తప్పక పోవాలి. కనిపించనిది పోవలేను.',
    'అఖండానికి ఎలాంటి లక్షణాలు లేవు, అయినప్పటికీ అన్ని లక్షణాలు దాని నుండి ఉద్భవిస్తాయి.',
    'మీరు పరమతత్త్వాన్ని ఒక వస్తువుగా తెలుసుకోలేరు, ఎందుకంటే మీరు అదే.',
    'ఆత్మ అనుభవించబడదు; అది అనుభవించేది.',
    'అన్ని ప్రశ్నలు నిలువబడినప్పుడు, సత్యం మిగిలి ఉంటుంది.',
    'మీకు ఏమీ జోడించాల్సిన అవసరం లేదు; కేవలం తప్పు ఆలోచనలను మాత్రమే తొలగించాలి.',
    'మీరు నిజంగా ఏమిటో అది ధృవీకరణ మరియు తిరస్కారానికి మించి ఉంది.',
    'నిశ్శబ్దంగా ఉండి, చూడండి — అది మాత్రమే.',
    'సత్యం సరళమైనది, కానీ మనస్సు సరళతకు వ్యతిరేకంగా ఉంటుంది.',
    'అది కూడా కరిగే వరకు ఉండే అనుభూతితో ఉండండి.',
    'సత్యాన్ని అర్థం చేసుకోవడానికి ప్రయత్నించకండి; అబద్ధం మీ నుండి దూరమవనీయండి.',
    'అర్థం చేసుకోవడం కీ, అనుభవం కాదు.',
    'ఏది నిజమో అది ఎప్పుడూ ఉనికిలో ఉంటుంది.',
    'మీరు కాలానికి ముందు ఉన్నారు.',
    'వాస్తవంలో ఎలాంటి తప్పు లేదు; మీ ఆలోచనలు మాత్రమే తప్పు.',
    'అన్వేషకుడు లయమైపోతే, అన్వేషితమయినది ప్రकटమవుతుంది.',
    'ఆలోచనల నుండి ఖాళీగా ఉండు.',
    'మీరు సాక్షి, చూసినది కాదు.',
    'మీరు ఉన్నారు — మరియు అది సరిపోతుంది.',
  ],
  [
    Article(
        heading: 'నేను ఎవరు? - ప్రాథమిక ప్రశ్న',
        body: 'నిసర్గదత్త మహారాజ్ యొక్క ఉపదేశం "నేను ఎవరు?" అనే ప్రాథమిక ప్రశ్న చుట్టూ తిరిగింది. ఆయన తన శిష్యులను అన్ని భావనలు మరియు గుర్తింపుల కంటే మించి వారి నిజమైన స్వరూపాన్ని పరిశీలించడానికి నిరంతరం ప్రేరేపించేవారు. \n\n"మీరు మీను మీరు అనుకుంటున్నట్లుగా కాదు," ఆయన చెప్పేవారు. "మీరు ఏమిటి అనేది కనుగొనండి." ఈ పరిశోధన ఒక బుద్ధి వ్యాయామం కాదు, \'నేను\' భావన యొక్క మూలాన్ని నేరుగా విచారించడమే.\n\nమహారాజ్ మనం సాధారణంగా శరీరం, మనసు, ఆలోచనలు, భావాలు మరియు జీవితంలో పోషించే వివిధ పాత్రలతో మనలను గుర్తించుకుంటామని బోధించారు. కానీ ఇవన్నీ చైతన్యంలో కనిపించే వస్తువులే. మేము కనిపించే అవగాహన, ఆ వస్తువులు కాదు. \n\nఆత్మ పరిశీలన ప్రక్రియ మీకు సంబంధించినది కాని అన్ని విషయాలను తిరస్కరించడం ద్వారా జరుగుతుంది - "నేను శరీరం కాదు, నేను మనస్సు కాదు, నేను ఆలోచనలు కాదు" - మీకు మిగిలినది ఏమిటో తెలుసుకునే వరకు. మిగిలినది శుద్ధ అవగాహన, శుద్ధ సత్యం, మీ నిజమైన స్వభావం.\n\n"మీరు ఏమిటి అనేది తెలుసుకోవాలంటే, మీరు ముందుగా మీరు ఏమి కాదు అనేది పరిశీలించి తెలుసుకోవాలి," మహారాజ్ చెప్పారు. ఈ తొలగింపు ప్రక్రియ మీ శుద్ధ అవగాహనగా ఉన్న ప్రాథమిక స్వభావాన్ని గుర్తించడానికి దారితీస్తుంది, అన్ని లక్షణాలు మరియు పరిమితుల కంటే మించి.\n\n"నేను ఎవరు?" అనే ప్రశ్నను తీవ్రమైన నిజాయితీతో మరియు నిబద్ధతతో అన్వేషించాలి. ఇది మేధస్సుతో అర్థం చేసుకోవడం సరిపోదు; ఇది మీ ఉనికిలో ప్రతి క్షణాన్ని వ్యాపించాల్సిన ఒక జీవించు విచారణగా మారాలి, దాని ద్వారా ప్రత్యేక వ్యక్తిగా ఉండే అబద్ధ భావన పూర్తిగా కరిగిపోతుంది.'
    ),
    Article(
        heading: 'చేతనత యొక్క స్వభావం',
        body: 'నిసర్గదత్త మహారాజ్ చైతన్యాన్ని వివరిస్తున్నప్పుడు ఒక ప్రత్యేకమైన పద్ధతిని అనుసరించారు, అది లోతైనదిగా మరియు అందరికీ అర్థమయ్యేలా ఉంది. ఆయన వ్యక్తిగత చైతన్యాన్ని (అతను "నేను ఉన్నాను" అనుభూతి అని పిలిచేవాడు) మరియు అనుభవానికి మించిన పరమ చైతన్యాన్ని వేరు చేసారు.\n\n"నేను ఉన్నాను" అనేది చైతన్యంలోని మొదటి చలనం, ఇది అన్ని ఇతర అనుభవాలకు పుట్టిన ప్రాథమిక భావన. మహారాజ్ ఈ శుద్ధ "నేను ఉన్నాను" అనుభూతిని "నేను ఇది" లేదా "నేను అది" వంటి అదనపు భావనలతో కలిపకుండా ఉంచాలని బోధించారు.\n\n"మీలో ఉన్న చైతన్యం మరియు నాలో ఉన్న చైతన్యం, స్పష్టంగా రెండు, ఒకటే" అని ఆయన చెప్పేవాడు. ఈ అవగాహన వేరుపడినదని భావించే మాయను కరిగించి, అన్ని స్పష్టమైన వైవిధ్యాలకు వెనుక ఉన్న ఐక్యతను ఆవిష్కరిస్తుంది.\n\nమహారాజ్ చైతన్యం మెదడు లేదా శరీరం ద్వారా ఉత్పత్తి కావడం లేదని వివరించారు. బదులుగా, శరీరం మరియు మెదడు చైతన్యంలో కనిపిస్తాయి. చైతన్యం వ్యక్తిగతం కాదు; ఇది విశ్వవ్యాప్తం, మరియు మనం వ్యక్తిగత చైతన్యంగా తీసుకునేది ఈ విశ్వ చైతన్యానికి కేవలం ప్రతిబింబం మాత్రమే. \n\nఅత్యంత వాస్తవం చైతన్యాన్ని మించినది - ఇది చైతన్యం స్వయంగా కనిపించి, మాయమవ్వే ఆది. ఇది మీ నిజమైన స్వభావం, చైతన్యానికి ముందు, ఉనికి మరియు అనుబంధానికి ముందు. \n\n"మీరు పరమ వాస్తవం," మహారాజ్ ప్రకటించేవారు. "చిన్న మనస్సు కాకండి." ఈ పరమ వాస్తవాన్ని ఒక వస్తువుగా తెలుసుకోవడం సాధ్యం కాదు ఎందుకంటే మీరు అదే. మీరు మీ గురించి ఆలోచించే అన్ని విషయాల క్షయంతో మాత్రమే ఇది గుర్తించబడుతుంది.'
    ),
    Article(
        heading: 'వ్యక్తి యొక్క మాయా',
        body: 'నిసర్గదత్త మహారాజ్ యొక్క అత్యంత విపరీతమైన ఉపదేశాలలో ఒకటి వ్యక్తి యొక్క మాయా స్వరూపం గురించి. ఆయన ఇలా చెప్పేవారు, "మీరు మీను ఒక వ్యక్తిగా భావిస్తారు, కానీ మీరు ఎప్పుడూ ఒక వ్యక్తిగా జన్మించలేదు."\n\nవ్యక్తి అనేది కేవలం జ్ఞాపకాలు, ఆలోచనలు మరియు గుర్తింపుల సమాహారం, ఇవి ఒక స్పష్టమైన కొనసాగింపును సృష్టిస్తాయి. కానీ దగ్గరగా పరిశీలించినప్పుడు, వ్యక్తి అని పిలవబడే ఏదీ స్థిరమైన అస్తిత్వం లేదు. ఇది ఒక సినిమాకి సమానం - వ్యక్తిగత ఫ్రేమ్‌లు కదలిక మరియు కథ యొక్క మాయను సృష్టిస్తున్నాయి.\n\nమహారాజ్ చెప్పారు, వ్యక్తి ఒక మానసిక నిర్మాణం, స్వతంత్ర వాస్తవం లేని భావనల సమూహం. "మీరు ఏమి అనుకుంటున్నారో, మీరు ఆ కాదు," అని ఆయన నొక్కి చెప్పారు. వ్యక్తి మీలో (చైతన్యం) కనిపిస్తుంది కానీ మీరు వ్యక్తి కాదు. \n\nఈ అవగాహన విముక్తి కలిగించేది ఎందుకంటే, ఇది వ్యక్తి యొక్క అన్ని సమస్యలు, పరిమితులు మరియు బాధలు కూడా మాయ మాత్రమే అని అర్థం. మీరు వ్యక్తి కాదు అని గ్రహించినప్పుడు, మీరు వ్యక్తి యొక్క విధి, karma మరియు పరిస్థితుల నుండి విముక్తి పొందుతారు.\n\n"మీరు perceivable చేసినది మీది కాదు. మీరు perceivable చేసినది మీతో సంబంధం లేదు," మహారాజ్ చెప్పేవారు. ఇది మనం సాధారణంగా మనదిగా భావించే శరీరం, మనసు, ఆలోచనలు మరియు భావనలు కూడా కలిగి ఉంటుంది.\n\nమీరు వ్యక్తి కాదు అని గుర్తించడం తాత్త్విక స్థితి కాదు, కానీ నిజమైన ఆత్మ-అన్వేషణ ద్వారా వచ్చే ప్రత్యక్ష అవగాహన. ఈ గుర్తింపు స్థిరంగా మరియు అచలంగా మారినప్పుడు, మీరు మీ నిజమైన స్వరూపంగా నివసిస్తారు - శుద్ధ అవగాహన, శుద్ధ అస్తిత్వం, అన్ని వ్యక్తిగత పరిమితుల కంటే మించి.'
    ),
    Article(
        heading: 'ప్రేమ మరియు జ్ఞానం - సత్యం యొక్క రెండు రెక్కలు',
        body: 'నిసర్గదత్త మహారాజ్ తన ప్రసిద్ధ వాక్యంలో ఆత్మవిశ్లేషణ యొక్క పరadoxను అందంగా వ్యక్తం చేశారు: "జ్ఞానం నాకు నేను ఏమీ కాదని చెబుతుంది. ప్రేమ నాకు నేను అన్నీ అని చెబుతుంది. ఈ రెండు మధ్య నా జీవితం ప్రవహిస్తుంది."\n\nజ్ఞానం అనేది మీ నిజమైన స్వభావాన్ని శుద్ధమైన అవగాహనగా గుర్తించడం, ఇది లక్షణాలు, రూపం, గుణాలు లేని - మానసికంగా పట్టుకోగలిగే ఏమీ లేదు. ఈ దృక్పథం నుండి, మీరు శూన్యం, అన్ని అనుభవాలు కనిపించే ఖాళీ.\n\nప్రేమ, మరోవైపు, ఈ అదే అవగాహన అన్ని కనిపించే వాటి యొక్క అసలు సారాన్ని గుర్తించడం. మీరు ఏదైనా నుండి వేరుగా లేరు; మీరు అనేక రూపాల్లో కనిపించే ఒకటే. ఇది మీ స్వయంగా అన్ని ఉనికిని ఆప్యాయంగా స్వీకరించే ప్రేమ.\n\nఇవి విరుద్ధమైన సత్యాలు కాదు, కానీ ఒకే ఆత్మవిశ్లేషణ యొక్క రెండు కోణాలు. అనంతం ఖాళీ మరియు సంపూర్ణత, శూన్యం మరియు సమస్తం, పరమాత్మ మరియు అంతరాత్మ. \n\n"నేను లోపల చూడగానే నేను శూన్యం అని తెలుసుకోవడం, అది జ్ఞానం. నేను బయట చూడగానే నేను సమస్తం అని తెలుసుకోవడం, అది ప్రేమ," మహారాజ్ వివరించారు. ఈ ద్వంద్వ గుర్తింపు సంపూర్ణ అవగాహన యొక్క లక్షణం.\n\nఈ అవగాహన ఆధారంగా జీవించడం అంటే, మీరు శూన్యం (ఏది కాదు) అని తెలుసుకోవడం ద్వారా శాంతిలో స్థిరంగా ఉండడం మరియు మీ స్వంత రూపంలో కనిపించే సమస్తాన్ని ప్రేమించడం. ఇది సాకారమైన జీవి యొక్క సహజ స్థితి - స్వీయాన్ని కోల్పోయి, అందరికీ ప్రేమతో నిండి ఉండటం.'
    ),
    Article(
        heading: 'జన్మ మరియు మరణం మించిపోయి',
        body: 'నిసర్గదత్త మహారాజ్ మరణం మరియు అమరత్వంపై చెప్పిన ఉపదేశాలు ప్రత్యేకంగా శక్తివంతమైనవి మరియు సాంత్వన కలిగించేలా ఉన్నాయి. "నిజం చనిపోదు, అసత్యం ఎప్పుడూ జీవించలేదు" అని ఆయన ఖచ్చితత్వంతో చెప్పేవారు.\n\nఅతని దృష్టిలో, మేము పుట్టడం మరియు చనడం అని పిలిచే వాటి అన్నీ మన చైతన్యంలో ఉన్న కేవలం రూపాలు, కలలలోని దృశ్యాల్లా ఉన్నాయి. శరీరం పుట్టి చనిపోతుంది, కానీ మీరు - శరీరం కనిపించే అవగాహన - ఎప్పుడూ పుట్టరు కాబట్టి చనిపోవడం అసాధ్యం.\n\n"మీరు మరణాన్ని భయపడుతున్నారు ఎందుకంటే మీరు మీను తెలుసుకోలేదు" అని మహారాజ్ సూచించేవారు. "నిజమైన మీరు మరణరహితుడు." ఈ మరణ భయం మృత శరీరంతో ఐక్యమవడం వల్ల వస్తుంది, అమర చైతన్యంగా మీను గుర్తించకపోవడం వల్ల.\n\nమహారాజ్ మేము నిజంగా పుట్టడం లేదా చనడం అనుభవించలేదని బోధించారు. మాకు గతం యొక్క జ్ఞాపకాలు మరియు భవిష్యత్తు గురించి ఊహలు ఉన్నాయి, కానీ మన నిజమైన అనుభవం ఎప్పుడూ ప్రస్తుత క్షణంలో ఉన్న అవగాహనతో ఉంటుంది. ఈ అవగాహన ఎప్పుడూ ఉంది మరియు ఎప్పుడూ ఉంటుంది.\n\nమీ మరణరహిత స్వభావాన్ని అర్థం చేసుకోవడం ఒక నమ్మకం లేదా సాంత్వన కాదు, కానీ ఒక ప్రత్యక్ష గుర్తింపు. మీరు నిజంగా మీను శుద్ధ అవగాహనగా తెలుసుకుంటే, మరణ భయం కేవలం అంతరించిపోతుంది ఎందుకంటే మీరు మరణించగలిగే ఏమీ లేదని గ్రహిస్తారు.\n\n"మీ బలహీనత మీకు ఈ ప్రపంచంలో జన్మించారని ఉన్న నమ్మకానికి కారణం," అని అతను చెప్పేవాడు. వాస్తవానికి, ప్రపంచం మీలో కనిపిస్తుంది; మీరు ప్రపంచంలో కనిపించడం లేదు. ఈ ప్రాథమిక అవగాహన మార్పు మీ జీవితానికి మరియు మరణానికి సంబంధించిన మీ మొత్తం సంబంధాన్ని మార్చుతుంది.\n\nఈ ఉపదేశం యొక్క ప్రాయోగిక అర్థం విస్తృతమైన స్వేచ్ఛ మరియు భయంలేని స్థితి. మీరు మీను మరణం లేని వాస్తవంగా తెలుసుకున్నప్పుడు, మీరు సంపూర్ణంగా జీవించగలరు మరియు మీ సహజ ఆనందం మరియు శాంతిని మబ్బుగా కప్పిపుచ్చే మరణం యొక్క నీడ లేకుండా పూర్తిగా ప్రేమించగలరు.'
    ),
  ],
);
